[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$tmp=Join-Path ([IO.Path]::GetTempPath()) ('hard-neg-'+[guid]::NewGuid().ToString('N'));try{& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\New-SyntheticProjectStoryHardening.ps1') -Destination $tmp|Out-Null;$x=Get-Content (Join-Path $tmp 'project-story.json') -Raw|ConvertFrom-Json;$x.tickets[0].comments=@($x.tickets[0].comments|? type -ne 'closing');$x|ConvertTo-Json -Depth 30|Set-Content (Join-Path $tmp 'project-story.json');& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\Test-SyntheticProjectStoryHardening.ps1') -Path $tmp|Out-Null;if($LASTEXITCODE -eq 0){throw 'STORY_CLOSING_COMMENT_ACCEPTED'};Write-Host 'PASS: Hardened story negative closure gate.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}}
